const result = $input.first().json;
if (result.exitCode !== undefined && result.exitCode !== 0) {
  throw new Error(`Python discovery failed with exit code ${result.exitCode}: ${result.stderr || 'no stderr'}`);
}
if (typeof result.stdout !== 'string' || !result.stdout.trim()) {
  throw new Error('Python discovery returned empty stdout');
}
let payload;
try {
  payload = JSON.parse(result.stdout);
} catch (error) {
  throw new Error(`Python discovery returned invalid JSON: ${error.message}`);
}
if (payload.contract_version !== 1 || !Array.isArray(payload.new_shows) || !Array.isArray(payload.seen_shows)) {
  throw new Error('Python discovery returned an unsupported contract');
}
return [{ json: payload }];
